section.programlisting:
OffsetAwareNormalizer pipeline = TextNormalizer.builder()
    .with(DehyphenationCharSequenceNormalizer.getInstance())
    .fullCaseFold()
    .buildAligned();

Document annotated = new RetokenizingTermVectorAnnotator(
    pipeline, WhitespaceTokenizer.INSTANCE).annotate(Document.of("word litiga-\ntion word"));
TermVector term = annotated.get(TermVectorAnnotator.TERM_VECTORS).get(1).value();
String original = term.spans().get(0).getCoveredText(annotated.text()).toString();
// term.term(): "litigation", term.frequency(): 1, original: "litiga-\ntion"
